# Local setup

Requirements: Node 22 or newer, pnpm, Docker.

```bash
pnpm install
pnpm run stack:up      # infra, migrations, build, all five apps
pnpm run stack:down    # stop apps and infra, keep the data
pnpm run stack:reset   # drop the data and start fresh
```

`stack:up` creates `.env` on first run through `scripts/make-local-env.sh`. The file holds throwaway local values, is gitignored and must never be committed. App logs go to `tmp/logs/`.

To run a second copy of the stack on the same machine, set `PORT_OFFSET` and `COMPOSE_PROJECT_NAME` before the first `stack:up`.

## Environment variables

| Name | Used by |
|---|---|
| `COMPOSE_PROJECT_NAME`, `PORT_OFFSET` | docker compose, `scripts/make-local-env.sh` |
| `NODE_ENV` | all apps. Not kept in `.env`, where it would leak into `next build`; `stack:up` sets `production` when it starts the apps |
| `DB_HOST`, `DB_PORT`, `DB_USERNAME`, `DB_PASSWORD`, `DB_DATABASE` | `booking`, `room`, migrations |
| `REDIS_HOST`, `REDIS_PORT` | `booking`, `worker` |
| `NATS_PORT` | docker compose |
| `NATS_URL` | `gateway`, `booking`, `room`, `worker` |
| `GATEWAY_PORT`, `WEB_ORIGIN` | `gateway` |
| `WEB_PORT`, `NEXT_PUBLIC_API_URL` | `web` |
import { PATTERN_METADATA } from '@nestjs/microservices/constants';
import { Test } from '@nestjs/testing';
import { PagedRoomsDto, RoomDto, RoomPatternEnum } from '@roombook/contract';
import { RoomController } from './room.controller';
import { RoomService } from './room.service';

describe('RoomController', () => {
  const room: RoomDto = { id: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10', name: 'Room 01', capacity: 2 };
  let controller: RoomController;
  let listRooms: jest.Mock;
  let findRoomById: jest.Mock;

  beforeEach(async () => {
    listRooms = jest.fn();
    findRoomById = jest.fn();
    const moduleRef = await Test.createTestingModule({
      controllers: [RoomController],
      providers: [{ provide: RoomService, useValue: { listRooms, findRoomById } }],
    }).compile();
    controller = moduleRef.get(RoomController);
  });

  it('answers the room list pattern', async () => {
    const paged: PagedRoomsDto = { items: [room], total: 12, page: 1, limit: 10 };
    listRooms.mockResolvedValue(paged);

    expect(Reflect.getMetadata(PATTERN_METADATA, RoomController.prototype.listRooms)).toEqual([RoomPatternEnum.LIST]);
    await expect(controller.listRooms({ page: 1, limit: 10 })).resolves.toBe(paged);
    expect(listRooms).toHaveBeenCalledWith({ page: 1, limit: 10 });
  });

  it('answers the find room by id pattern', async () => {
    findRoomById.mockResolvedValue(room);

    expect(Reflect.getMetadata(PATTERN_METADATA, RoomController.prototype.findRoomById)).toEqual([
      RoomPatternEnum.FIND_BY_ID,
    ]);
    await expect(controller.findRoomById({ id: room.id })).resolves.toBe(room);
    expect(findRoomById).toHaveBeenCalledWith(room.id);
  });
Specs:
  booking-confirmation     requirements 6
  booking-idempotency      requirements 8
  bookings-api             requirements 14
  bookings-page            requirements 9

